test('invoiceTotals calculates total with voucher correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const totals1 = invoiceTotals(invoiceResult.value);
  const totalWithoutVoucher = totals1.total;

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'SAVE10', amount: 5000 });
