});

test('removeLine does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
