      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
    ],
  });
  assert.equal(invoiceResult.ok, true);

  const totals1 = invoiceTotals(invoiceResult.value);

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'GOLD', amount: 2000 });
  assert.equal(voucherResult.ok, true);

  const totals2 = invoiceTotals(voucherResult.value);
  assert.equal(totals2.voucher, 2000);
  assert.equal(totals2.total, totals1.total - 2000);
});

