test('invoiceTotals integrates with createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const expectedSubtotal = 5 * 8500 + 5 * 9500; // 90000
  const expectedVat = Math.round(42500 * 21 / 100) + Math.round(47500 * 21 / 100); // 8925 + 9975 = 18900
  const expectedTotal = expectedSubtotal + expectedVat; // 108900
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

