test('lineBulkDiscount returns 0 for lines with less than 10 units', () => {
  assert.equal(lineBulkDiscount({ qty: 1, unitPrice: 8500, discountPercent: 0 }), 0);
  assert.equal(lineBulkDiscount({ qty: 5, unitPrice: 8500, discountPercent: 0 }), 0);
  assert.equal(lineBulkDiscount({ qty: 9, unitPrice: 8500, discountPercent: 0 }), 0);
});

test('lineBulkDiscount returns 2.5% of amount after first discount for 10+ units', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 21 };
  const total = 100000;
  const firstDiscount = 0;
  const amountAfterFirstDiscount = total - firstDiscount;
  const expectedBulkDiscount = Math.round(amountAfterFirstDiscount * 0.025);
  assert.equal(lineBulkDiscount(line), expectedBulkDiscount);
});

test('lineBulkDiscount applies after line discount', () => {
  const line = { qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 };
