});

test('lineVat with 9% VAT rate', () => {
  const line = { qty: 8, unitPrice: 37, discountPercent: 0, vatRate: 9 };
  const vat = lineVat(line);
  const lineTotal = 8 * 37; // 296
  const expectedVat = 27; // 296 * 9 / 100 = 26.64 -> 27 (banker's rounding)
  assert.equal(vat, expectedVat);
});

test('lineVat clamps to 0', () => {
