  const line1Total = 5 * 8500; // 42500
  const line1Vat = Math.round(42500 * 21 / 100); // 8925

  const line2Total = 8 * 37; // 296
  const line2Vat = Math.round(296 * 9 / 100); // 27

  const expectedSubtotal = line1Total + line2Total; // 42796
  const expectedVat = line1Vat + line2Vat; // 8952
  const expectedTotal = expectedSubtotal + expectedVat; // 51748

  assert.equal(totals.subtotal, expectedSubtotal);
