  const voucherResult = applyVoucher(invoiceResult.value, { code: 'SAVE10', amount: 1000 });
  assert.equal(voucherResult.ok, true);

  const totals = invoiceTotals(voucherResult.value);
  assert.equal(totals.voucher, 1000);
});

test('invoiceTotals calculates total with voucher correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const totals1 = invoiceTotals(invoiceResult.value);
  const totalWithoutVoucher = totals1.total;

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(voucherResult.ok, true);

  const totals2 = invoiceTotals(voucherResult.value);
  assert.equal(totals2.total, totalWithoutVoucher - 5000);
});

test('invoiceTotals returns voucher 0 for invoices without voucher', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const totals = invoiceTotals(invoiceResult.value);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals clamps total to 0 even with voucher', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'SAVE', amount: 999999999 });
  assert.equal(voucherResult.ok, true);

  const totals = invoiceTotals(voucherResult.value);
  assert.equal(totals.total, 0);
});

test('applyVoucher works with discounts and VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
    ],
  });
  assert.equal(invoiceResult.ok, true);

  const totals1 = invoiceTotals(invoiceResult.value);

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'GOLD', amount: 2000 });
  assert.equal(voucherResult.ok, true);

  const totals2 = invoiceTotals(voucherResult.value);
  assert.equal(totals2.voucher, 2000);
  assert.equal(totals2.total, totals1.total - 2000);
});

