  assert.equal(result.value.dueDate, '2027-01-14');
});

test('applyVoucher applies a voucher to a draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'SAVE10', amount: 1000 });
  assert.equal(voucherResult.ok, true);
  assert.deepEqual(voucherResult.value.voucher, { code: 'SAVE10', amount: 1000 });
});

test('applyVoucher reports NOT_DRAFT for issued invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);

  const voucherResult = applyVoucher(issuedResult.value, { code: 'SAVE10', amount: 1000 });
  assert.deepEqual(voucherResult, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher reports VOUCHER_EXISTS if invoice already has a voucher', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
