  const voucherResult = applyVoucher(invoiceResult.value, { code: 'SAVE', amount: 999999999 });
  assert.equal(voucherResult.ok, true);

  const totals = invoiceTotals(voucherResult.value);
  assert.equal(totals.total, 0);
});

test('applyVoucher works with discounts and VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
    ],
  });
