test('invoiceTotals includes discount and calculates total correctly', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 },
    ],
  });
  assert.equal(result.ok, true);

  const totals = invoiceTotals(result.value);
  const line1Total = 5 * 8500; // 42500
  const line1Discount = line1Total * 10 / 100; // 4250
  const line1BaseAmount = line1Total - line1Discount; // 38250
  const line1Vat = Math.round(line1BaseAmount * 21 / 100); // 8033 (banker's rounding: 8032.5 rounds to even -> 8032, but Math.round rounds .5 up)
  const line2Total = 5 * 9500; // 47500
  const line2Vat = Math.round(line2Total * 21 / 100); // 9975
  const expectedSubtotal = line1Total + line2Total; // 90000
  const expectedDiscount = line1Discount; // 4250
  const expectedVat = line1Vat + line2Vat; // 18008
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVat; // 103758

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

