      { sku: 'PRINT-A4', qty: 8 },
    ],
  });
  assert.equal(result.ok, true);

  const totals = invoiceTotals(result.value);

  const line1Total = 5 * 8500; // 42500
  const line1Vat = Math.round(42500 * 21 / 100); // 8925

  const line2Total = 8 * 37; // 296
  const line2Vat = Math.round(296 * 9 / 100); // 27

  const expectedSubtotal = line1Total + line2Total; // 42796
  const expectedVat = line1Vat + line2Vat; // 8952
  const expectedTotal = expectedSubtotal + expectedVat; // 51748

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals with discount and VAT', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 20 },
    ],
  });
  assert.equal(result.ok, true);

  const totals = invoiceTotals(result.value);

  const lineTotal = 5 * 8500; // 42500
  const discount = lineTotal * 20 / 100; // 8500
  const baseAmount = lineTotal - discount; // 34000
  const vat = Math.round(baseAmount * 21 / 100); // 7140
  const total = lineTotal - discount + vat; // 42500 - 8500 + 7140 = 41140

  assert.equal(totals.subtotal, lineTotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, total);
});

