  assert.match(lines[4], /^VAT:/);
  assert.match(lines[5], /^Total:/);
});

test('renderInvoiceText shows discount in line item', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);

  const text = renderInvoiceText(result.value);
