test('lateFee accounts for partial payments', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv.ok, true);

  let issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total / 2, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const feeOverdue = lateFee(paid.value, '2026-11-07');
  const expectedDue = totals.total - Math.floor(totals.total / 2);
  const expectedFee = Math.round(expectedDue * 1 * 0.0004);

  assert.equal(feeOverdue, expectedFee);
});

